CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_Report_StockTransferHistory`(IN p_TenantId CHAR(36),IN p_DateFrom DATE,IN p_DateTo DATE,IN p_Page INT,IN p_PageSize INT)
BEGIN DECLARE v_Offset INT DEFAULT 0;IF p_Page IS NULL OR p_Page<1 THEN SET p_Page=1;END IF;IF p_PageSize IS NULL OR p_PageSize<1 THEN SET p_PageSize=50;END IF;SET v_Offset=(p_Page-1)*p_PageSize;
DROP TEMPORARY TABLE IF EXISTS tmp;CREATE TEMPORARY TABLE tmp AS SELECT st.transfer_number,st.transfer_date,st.status,st.notes,fw.name AS from_warehouse,tw.name AS to_warehouse FROM StockTransfers st JOIN warehouses fw ON fw.id=st.from_warehouse_id JOIN warehouses tw ON tw.id=st.to_warehouse_id WHERE st.tenant_id=p_TenantId AND (p_DateFrom IS NULL OR st.transfer_date>=p_DateFrom) AND (st.transfer_date<=p_DateTo OR p_DateTo IS NULL);
SELECT COUNT(*) AS total_transfers FROM tmp;
SELECT transfer_number,transfer_date,status,from_warehouse,to_warehouse,notes FROM tmp ORDER BY transfer_date DESC LIMIT p_PageSize OFFSET v_Offset;
SELECT COUNT(*) AS total FROM tmp;DROP TEMPORARY TABLE tmp;END ;;
DELIMITER ;
